import sys

def calc(expr: str) -> int | str:
    sys.setrecursionlimit(1000000)
    s = expr
    n = len(s)
    i = 0

    class Err(Exception):
        pass

    def skip():
        nonlocal i
        while i < n and s[i] == ' ':
            i += 1

    def parse_expr():
        nonlocal i
        val = parse_term()
        while True:
            skip()
            if i < n and s[i] in '+-':
                op = s[i]
                i += 1
                rhs = parse_term()
                val = val + rhs if op == '+' else val - rhs
            else:
                return val

    def parse_term():
        nonlocal i
        val = parse_unary()
        while True:
            skip()
            if i < n and s[i] in '*/%':
                op = s[i]
                i += 1
                rhs = parse_unary()
                if op == '*':
                    val *= rhs
                else:
                    if rhs == 0:
                        raise Err()
                    if op == '/':
                        q = abs(val) // abs(rhs)
                        val = -q if (val < 0) != (rhs < 0) else q
                    else:
                        q = abs(val) // abs(rhs)
                        if (val < 0) != (rhs < 0):
                            q = -q
                        val = val - rhs * q
            else:
                return val

    def parse_unary():
        nonlocal i
        skip()
        neg = False
        while i < n and s[i] == '-':
            neg = not neg
            i += 1
            skip()
        val = parse_power()
        return -val if neg else val

    def parse_power():
        nonlocal i
        base = parse_atom()
        skip()
        if i < n and s[i] == '^':
            i += 1
            exp = parse_unary()
            if exp < 0:
                raise Err()
            return pow(base, exp)
        return base

    def parse_atom():
        nonlocal i
        skip()
        if s[i] == '(':
            i += 1
            val = parse_expr()
            skip()
            i += 1  # ')'
            return val
        j = i
        while i < n and s[i].isdigit():
            i += 1
        return int(s[j:i])

    try:
        result = parse_expr()
        return result
    except Err:
        return "error"
